rules:
[data-theme="every-option"] h1 { text-align: center; border-bottom: 0; padding-bottom: 0.15em; background-image: linear-gradient(90deg, var(--accent), var(--heading)); background-size: 64px 4px; background-repeat: no-repeat; background-position: left bottom; }
[data-theme="every-option"] h2 { font-style: italic; border-bottom: 0; padding-bottom: 0; }
[data-theme="every-option"] h2::before { content: ""; display: inline-block; width: 0.5em; height: 0.5em; margin-right: 0.45em; border-radius: 50%; background: var(--accent); vertical-align: 0.12em; }
[data-theme="every-option"] blockquote { font-style: italic; border-left: 0; padding: 0.6em 1em; background: var(--surface); border-radius: var(--radius); color: var(--fg); }
[data-theme="every-option"] hr { height: 4px; border-radius: 2px; background: linear-gradient(90deg, var(--accent), var(--heading), var(--link)); }
[data-theme="every-option"] th { background: var(--heading); color: var(--bg); border-color: var(--heading); border-left: 0; border-right: 0; }
[data-theme="every-option"] td { border-left: 0; border-right: 0; }
[data-theme="every-option"] table { border-radius: var(--radius); }
[data-theme="every-option"] li::marker { color: var(--muted); }
[data-theme="every-option"] code:not(pre code) { color: var(--hl-keyword); }
[data-theme="every-option"] a { text-decoration: underline; text-underline-offset: 0.15em; text-decoration-thickness: 1px; }
[data-theme="every-option"] .hljs-keyword { font-weight: 650; }
[data-theme="every-option"] .hljs-title { font-weight: 650; }

variables:
:root[data-theme="every-option"] {
  --bg: #FFFDFB;
  --surface: #F6F0EC;
  --fg: #26211F;
  --muted: #6F6660;
  --border: #EADFD8;
  --heading: #26211F;
  --accent: #C8471B;
  --link: #B03C0C;
  --quote: #D97A4A;
  --hl-keyword: #B03C0C;
  --hl-string: #2F6F5E;
  --hl-comment: #746B66;
  --hl-number: #9A5B00;
  --hl-function: #5B3E8C;
  --hl-type: #1F6FB2;
  --mm-node: #FBE9E0;
  --mm-border: #CA6C3C;
  --mm-text: #26211F;
  --mm-line: #8A6A5C;
  --mm-secondary: #E6F1EE;
  --mm-tertiary: #FFF6F1;
  --mm-note: #FFF1D6;
  --font-body: -apple-system, BlinkMacSystemFont, "Helvetica Neue", "PingFang TC", "PingFang SC", sans-serif;
}
@media (prefers-color-scheme: dark) {
  :root[data-theme="every-option"] {
  --bg: #1C1A1F;
  --surface: #262229;
  --fg: #EBE4DF;
  --muted: #A39992;
  --border: #3A343A;
  --heading: #F4EEEA;
  --accent: #FF8A50;
  --link: #FF9E6B;
  --quote: #E08A5C;
  --hl-keyword: #FF9E6B;
  --hl-string: #7FD1B9;
  --hl-comment: #938A84;
  --hl-number: #F2C572;
  --hl-function: #C7A6F5;
  --hl-type: #6CB6FF;
  --mm-node: #3A2A26;
  --mm-border: #E08A5C;
  --mm-text: #EBE4DF;
  --mm-line: #B8A69C;
  --mm-secondary: #23332F;
  --mm-tertiary: #2B2427;
  --mm-note: #3D3322;
  }
}
